package pt.qpetiscos.agenda;
import android.content.*;import org.json.*;
public class NotesWidgetClick extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){int id=i.getIntExtra("wid",-1);String op=i.getStringExtra("op"),key=i.getStringExtra("event");if(id<0||op==null||key==null||!key.matches("[a-fA-F0-9-]{36}"))return;if("view".equals(op)){try{WidgetAgenda.open(c,id,"qp=note&id="+key).send();}catch(Exception ignored){}return;}if("expand".equals(op)){android.content.SharedPreferences p=NotesWidget.prefs(c);String k="expand"+id+key;p.edit().putBoolean(k,!p.getBoolean(k,false)).apply();NotesWidget.render(c,id,"");return;}if(WidgetAgenda.readOnly(c)||!("complete".equals(op)||"read".equals(op)))return;PendingResult pending=goAsync();Context a=c.getApplicationContext();WidgetAgenda.runAsync(()->{try{if(WidgetAgenda.readOnly(a))return;JSONObject s=WidgetAgenda.session(a);String uid=s.getString("uid");JSONArray found=new JSONArray(NotesWidget.get(a,s,"internal_notes","?select=id,kind,important,completed,updated_at&id=eq."+key+"&user_id=eq."+uid+"&deleted_at=is.null"));if(found.length()!=1)return;JSONObject n=found.getJSONObject(0);if("complete".equals(op)&&NotesWidget.task(n)&&!n.optBoolean("completed")){String query="?id=eq."+key+"&user_id=eq."+uid+"&deleted_at=is.null&completed=eq.false&updated_at=eq."+android.net.Uri.encode(n.getString("updated_at"));JSONArray changed=new JSONArray(WidgetAgenda.requestTable(a,s,"internal_notes","PATCH",query,new JSONObject().put("completed",true).put("updated_by",s.getString("device"))));if(changed.length()!=1)throw new java.io.IOException("Concurrent update");}else if("read".equals(op)&&!NotesWidget.task(n)&&n.optBoolean("important")){WidgetAgenda.requestTable(a,s,"internal_note_reads","POST","",new JSONObject().put("note_id",key).put("user_id",uid).put("device_id",s.getString("device")).put("note_revision",n.getString("updated_at")));}NotesWidget.sync(a);}catch(Exception e){new android.os.Handler(android.os.Looper.getMainLooper()).post(()->android.widget.Toast.makeText(a,"Não foi possível guardar a alteração",android.widget.Toast.LENGTH_SHORT).show());}finally{pending.finish();}});}
}